prompt:
Implement a bump allocator over caller-provided memory:

```c
typedef struct { unsigned char *mem; size_t cap; size_t used; } arena_t;
void arena_init(arena_t *a, unsigned char *buf, size_t cap);
void *arena_alloc(arena_t *a, size_t n);
void arena_reset(arena_t *a);
```

`arena_alloc` returns NULL when the request does not fit the remaining capacity; `arena_reset` rewinds `used` to 0.

tests.code:
unsigned char buf[64];
arena_t a;
arena_init(&a, buf, sizeof buf);
unsigned char *p1 = arena_alloc(&a, 16);
unsigned char *p2 = arena_alloc(&a, 40);
CHECK_EQ((int)(p1 - buf), 0);
CHECK_EQ((int)(p2 - buf), 16);

unsigned char buf[64];
arena_t a;
arena_init(&a, buf, sizeof buf);
arena_alloc(&a, 56);
CHECK_NULL(arena_alloc(&a, 16));

unsigned char buf[64];
arena_t a;
arena_init(&a, buf, sizeof buf);
arena_alloc(&a, 32);
arena_reset(&a);
CHECK_NOT_NULL(arena_alloc(&a, 64));
